from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from typing import Optional


class PromotionExpiredError(Exception):
    """Raised when an order references a promotion past its expiry."""

    def __init__(self, code: str, expired_at: datetime):
        super().__init__(f"Promotion {code!r} expired at {expired_at.isoformat()}")
        self.code = code
        self.expired_at = expired_at


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


def checkout_total(subtotal: Decimal, promotion: Optional[Promotion], now: datetime) -> Decimal:
    # Policy is pending product decision: currently expired promotions reject the order.
    if promotion is None:
        return subtotal
    if now >= promotion.expires_at:
        raise PromotionExpiredError(promotion.code, promotion.expires_at)
    return (subtotal * (1 - promotion.percent_off / 100)).quantize(Decimal("0.01"))
EOF
cat > test_checkout.py <<'EOF'
from datetime import datetime, timedelta
from decimal import Decimal

import pytest

from checkout import Promotion, PromotionExpiredError, checkout_total

NOW = datetime(2026, 1, 1, 12, 0)


def promo(expires_at):
    return Promotion("SAVE10", Decimal("10"), expires_at)


def test_no_promotion():
    assert checkout_total(Decimal("100.00"), None, NOW) == Decimal("100.00")


def test_valid_promotion_applied():
    assert checkout_total(Decimal("100.00"), promo(NOW + timedelta(days=1)), NOW) == Decimal("90.00")


def test_expired_promotion_rejected():
    with pytest.raises(PromotionExpiredError) as e:
        checkout_total(Decimal("100.00"), promo(NOW - timedelta(seconds=1)), NOW)
    assert e.value.code == "SAVE10"


def test_promotion_expiring_exactly_now_is_expired():
    with pytest.raises(PromotionExpiredError):
        checkout_total(Decimal("100.00"), promo(NOW), NOW)
EOF
python -m pytest -q 2>&1 | tail -3

